import java.util.PriorityQueue

fun mergeKArrays(arrays: List<IntArray>): List<Int> {
    // heap holds [value, arrayIndex, elementIndex]
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })
    for ((i, arr) in arrays.withIndex()) {
        if (arr.isNotEmpty()) minHeap.add(intArrayOf(arr[0], i, 0))
    }
    val result = mutableListOf<Int>()
    while (minHeap.isNotEmpty()) {
        val (value, arrIdx, elemIdx) = minHeap.poll()
        result.add(value)
        val next = elemIdx + 1
        if (next < arrays[arrIdx].size) {
            minHeap.add(intArrayOf(arrays[arrIdx][next], arrIdx, next))
        }
    }
    return result
}
// Time: O(N log K)   Space: O(K) heap + O(N) output

import java.util.PriorityQueue

class ListNode(var `val`: Int) {
    var next: ListNode? = null
}

fun mergeKLists(lists: Array<ListNode?>): ListNode? {
    val minHeap = PriorityQueue<ListNode>(compareBy { it.`val` })
    for (head in lists) {
        if (head != null) minHeap.add(head)
    }
    val dummy = ListNode(0)
    var tail = dummy
    while (minHeap.isNotEmpty()) {
        val node = minHeap.poll()
        tail.next = node
        tail = node
        node.next?.let { minHeap.add(it) }
    }
    return dummy.next
}
// Time: O(N log K)   Space: O(K)

fun mergeKListsDC(lists: Array<ListNode?>): ListNode? {
    if (lists.isEmpty()) return null
    var step = 1
    val work = lists.copyOf()
    while (step < work.size) {
        var i = 0
        while (i + step < work.size) {
            work[i] = mergeTwo(work[i], work[i + step])
            i += step * 2
        }
        step *= 2
    }
    return work[0]
}

fun mergeTwo(a: ListNode?, b: ListNode?): ListNode? {
    val dummy = ListNode(0)
    var tail = dummy
    var l1 = a
    var l2 = b
    while (l1 != null && l2 != null) {
        if (l1.`val` <= l2.`val`) { tail.next = l1; l1 = l1.next }
        else { tail.next = l2; l2 = l2.next }
        tail = tail.next!!
    }
    tail.next = l1 ?: l2
    return dummy.next
}
// Time: O(N log K)   Space: O(1) extra

fun mergeTwoLists(list1: ListNode?, list2: ListNode?): ListNode? {
    val dummy = ListNode(0)
    var tail = dummy
    var a = list1
    var b = list2
    while (a != null && b != null) {
        if (a.`val` <= b.`val`) { tail.next = a; a = a.next }
        else { tail.next = b; b = b.next }
        tail = tail.next!!
    }
    tail.next = a ?: b          // attach the leftover
    return dummy.next
}
// Time: O(n + m)   Space: O(1)

import java.util.PriorityQueue

fun kthSmallest(matrix: Array<IntArray>, k: Int): Int {
    val n = matrix.size
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })
    for (r in 0 until minOf(n, k)) {
        minHeap.add(intArrayOf(matrix[r][0], r, 0))      // first element of each row
    }
    var result = 0
    repeat(k) {
        val (value, r, c) = minHeap.poll()
        result = value
        if (c + 1 < n) minHeap.add(intArrayOf(matrix[r][c + 1], r, c + 1))
    }
    return result
}
// Time: O(k log min(n, k))   Space: O(min(n, k))

import java.util.PriorityQueue

fun smallestRange(nums: List<List<Int>>): IntArray {
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })  // [value, list, index]
    var currentMax = Int.MIN_VALUE
    for ((i, list) in nums.withIndex()) {
        minHeap.add(intArrayOf(list[0], i, 0))
        currentMax = maxOf(currentMax, list[0])
    }
    var rangeStart = 0
    var rangeEnd = Int.MAX_VALUE
    while (minHeap.size == nums.size) {          // one element from every list
        val (value, listIdx, elemIdx) = minHeap.poll()
        if (currentMax - value < rangeEnd - rangeStart) {
            rangeStart = value
            rangeEnd = currentMax
        }
        if (elemIdx + 1 == nums[listIdx].size) break     // a list is exhausted
        val next = nums[listIdx][elemIdx + 1]
        minHeap.add(intArrayOf(next, listIdx, elemIdx + 1))
        currentMax = maxOf(currentMax, next)
    }
    return intArrayOf(rangeStart, rangeEnd)
}
// Time: O(N log K)   Space: O(K)

import java.util.PriorityQueue

fun kSmallestPairs(nums1: IntArray, nums2: IntArray, k: Int): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    if (nums1.isEmpty() || nums2.isEmpty()) return result
    // each nums1[i] is a 'list' of sums with nums2
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })   // [sum, i, j]
    for (i in 0 until minOf(nums1.size, k)) {
        minHeap.add(intArrayOf(nums1[i] + nums2[0], i, 0))
    }
    while (result.size < k && minHeap.isNotEmpty()) {
        val (_, i, j) = minHeap.poll()
        result.add(listOf(nums1[i], nums2[j]))
        if (j + 1 < nums2.size) {
            minHeap.add(intArrayOf(nums1[i] + nums2[j + 1], i, j + 1))
        }
    }
    return result
}
// Time: O(k log k)   Space: O(k)

fun mergeInPlace(nums1: IntArray, m: Int, nums2: IntArray, n: Int) {
    var i = m - 1
    var j = n - 1
    var k = m + n - 1
    while (j >= 0) {
        nums1[k--] = if (i >= 0 && nums1[i] > nums2[j]) nums1[i--] else nums2[j--]
    }
}
// Time: O(m + n)   Space: O(1)
