fun nthUglyNumber(n: Int): Int {
    val ugly = IntArray(n)
    ugly[0] = 1
    var i2 = 0
    var i3 = 0
    var i5 = 0
    for (i in 1 until n) {
        val next2 = ugly[i2] * 2
        val next3 = ugly[i3] * 3
        val next5 = ugly[i5] * 5
        val next = minOf(next2, next3, next5)
        ugly[i] = next
        if (next == next2) i2++            // advance every list that produced 'next'
        if (next == next3) i3++
        if (next == next5) i5++
    }
    return ugly[n - 1]
}
// Time: O(n)   Space: O(n)
