import java.util.PriorityQueue

class StreamEntry<T>(val value: T, val source: Int)

fun <T : Comparable<T>> mergeSorted(iterators: List<Iterator<T>>): Sequence<T> = sequence {
    val heap = PriorityQueue<StreamEntry<T>>(compareBy { it.value })
    for ((i, iterator) in iterators.withIndex()) {
        if (iterator.hasNext()) heap.add(StreamEntry(iterator.next(), i))
    }
    while (heap.isNotEmpty()) {
        val entry = heap.poll()
        yield(entry.value)
        val source = iterators[entry.source]
        if (source.hasNext()) heap.add(StreamEntry(source.next(), entry.source))
    }
}
// Time: O(N log K)   Space: O(K)   Lazy: never holds all N items

// To find the median of K sorted arrays with total N elements:
// 1. Merge with a min heap until you have popped N / 2 + 1 elements.
// 2. If N is odd, the last popped value is the median.
// 3. If N is even, average the last two popped values.

import java.util.PriorityQueue

fun medianOfKArrays(arrays: List<IntArray>): Double {
    val total = arrays.sumOf { it.size }
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })
    for ((i, arr) in arrays.withIndex()) {
        if (arr.isNotEmpty()) minHeap.add(intArrayOf(arr[0], i, 0))
    }
    var prev = 0
    var curr = 0
    repeat(total / 2 + 1) {
        prev = curr
        val (value, a, idx) = minHeap.poll()
        curr = value
        if (idx + 1 < arrays[a].size) minHeap.add(intArrayOf(arrays[a][idx + 1], a, idx + 1))
    }
    return if (total % 2 == 1) curr.toDouble() else (prev + curr) / 2.0
}
// Time: O((N / 2) log K)   Space: O(K)
